import { DateHelper, TodayHelper, isNonEmptyArray } from "@/core/helpers";
import { useFetchAllQueueTimes } from "@/core/hooks";
import { OpeningHoursItem, PlcQueueStoppageFlag, QueueTimeItem } from "@parksandresorts/webapiproxy-types";
import {
  getActiveOpeningWindow,
  getActiveOpeningWindowFromOpeningHours,
  operatingTimeVisibleInsidePark as visibleInsidePark,
} from "./get-active-opening-window";
import { orderBy } from "lodash-es";

/** All possible queue states for rides */
export const queueDisplayQueueStates = ["open", "temporarilyClosed", "notOperational"] as const;
export type QueueDisplayQueueState = (typeof queueDisplayQueueStates)[number];

/** Status when ride is temporarily closed or closed, undefined if ride is open */
export type QueueDisplayRideStoppageStatus = PlcQueueStoppageFlag | undefined;

/** Bilingual category title (English/Swedish) */
export type QueueDisplayCategoryTitle = {
  en: string;
  sv: string;
};

/** Single ride with all display information */
export type QueueDisplayRide = {
  rideId: number;
  rideTitle: string;
  rideCategory: QueueDisplayCategoryTitle;
  displayState: RideDisplayData;
};

/** Category containing rides grouped by queue state */
export type QueueDisplayDataCategory = {
  category: QueueDisplayCategoryTitle;
  rides: Record<QueueDisplayQueueState, Array<QueueDisplayRide>>;
};

/** Ride data including queue time data (QueueTimeItem) */
export type QueueDisplayRideBlock = {
  title: string;
  categoryTitle: QueueDisplayCategoryTitle;
  rideId: number;
  queueTimeObject?: QueueTimeItem;
};

/** Result of queue data processing for a single ride */
export type QueueDisplayRideQueueData = {
  queueState: QueueDisplayQueueState;
  queueTime: string;
  stoppageStatus: QueueDisplayRideStoppageStatus;
};

/** Single column of display data */
export type QueueDisplayColumn = {
  columnTitle: QueueDisplayCategoryTitle;
  rows: Array<QueueDisplayRide>;
};

const allowedQueueTimeStates = [0, 1, 2] as const;
const allowedQueueTimeState = (state: number): state is (typeof allowedQueueTimeStates)[number] =>
  allowedQueueTimeStates.includes(state as (typeof allowedQueueTimeStates)[number]);

/** Get ride state info for given ride
 * @returns
 * - Ride state (open, temporarily closed or closed)
 * - Queue time (if open)
 * - Stoppage status (if temporarily closed or closed)
 */
export function getRideQueueData(queueTimeItem: QueueTimeItem | undefined): QueueDisplayRideQueueData {
  switch (queueTimeItem?.state) {
    // State 0: The ride is open and operational
    case 0:
      return {
        queueState: "open" as QueueDisplayQueueState,
        queueTime: queueTimeItem?.queueTimeText || "-",
        stoppageStatus: undefined,
      };
    // State 1: The ride is closed for the day (or longer)
    case 1:
      return {
        queueState: "notOperational" as QueueDisplayQueueState,
        queueTime: "",
        stoppageStatus: queueTimeItem?.stoppage || PlcQueueStoppageFlag.CLOSED_REST_OF_DAY,
      };
    // State 2: The ride is temporarily closed and will open later during the day
    case 2:
    default:
      return {
        queueState: "temporarilyClosed" as QueueDisplayQueueState,
        queueTime: "",
        stoppageStatus: queueTimeItem?.stoppage || PlcQueueStoppageFlag.OTHER_STOPPAGE,
      };
  }
}

export type RideDisplayData =
  | {
      /** used when the park is not supposed to open today, or if we get invalid state information */
      state: "NOT_OPEN_TODAY";
    }
  | {
      /** the attraction will open some time today, but has not yet */
      state: "OPENS_SOON";
      openingTime: string;
      closingTime: string | null;
    }
  | {
      /** the attraction is open: show the current queue time (with or without closing time) */
      state: "QUEUE_TIME";
      queueData: ReturnType<typeof getRideQueueData>;
      closingTime: string | null;
    }
  | {
      /** the attraction is closed (temporarily or for the rest of the day/pass) */
      state: "CLOSED";
      queueData: ReturnType<typeof getRideQueueData>;
    };

export function displayStateAndQueueData(
  queueTime: QueueTimeItem | undefined,
  openingHours: OpeningHoursItem | undefined,
  now: Date,
): RideDisplayData {
  // The attraction is not supposed to open today at all
  if (!openingHours || !queueTime || !isNonEmptyArray(queueTime.schedule?.today?.operatingTimes)) {
    return { state: "NOT_OPEN_TODAY" };
  }
  if (!allowedQueueTimeState(queueTime.state)) {
    // this is an invalid state, and we cannot handle it gracefully
    console.error("Got invalid queueTime.state", queueTime.state);
    return { state: "NOT_OPEN_TODAY" };
  }

  const passOpeningHours = getActiveOpeningWindowFromOpeningHours(openingHours, now);

  const schedule = queueTime.schedule?.today?.operatingTimes ?? [];
  const operatingTime = getActiveOpeningWindow(
    schedule
      .filter((o) => visibleInsidePark(o))
      .map((ot) => ({
        from: ot.opensOn,
        to: ot.closesOn,
      })),
    passOpeningHours,
    now,
  );

  // if the attraction closes at a time different than the rest of the park, we should return it
  const closingTime = DateHelper.isEqualYYYYMMDDHHMM(operatingTime.to, passOpeningHours.to)
    ? null
    : DateHelper.toStringTimeHHMM(operatingTime.to);

  if (queueTime.state === 0) {
    return {
      state: "QUEUE_TIME",
      queueData: getRideQueueData(queueTime),
      closingTime,
    };
  }

  // If we do not have a `stoppage` reason even though we have a closed state, we can assume that the attraction will open later today
  const explicitlyClosed = !!queueTime.stoppage;

  if (DateHelper.isBefore(now, operatingTime.from) && !explicitlyClosed) {
    return {
      state: "OPENS_SOON",
      openingTime: DateHelper.toStringTimeHHMM(operatingTime.from),
      closingTime,
    };
  }

  return {
    state: "CLOSED",
    queueData: getRideQueueData(queueTime),
  };
}

/** Group rides by category and queue state within each category */
function getGroupedRides(rides: Array<QueueDisplayRide>): Array<QueueDisplayDataCategory> {
  const categoryMap = new Map<string, QueueDisplayDataCategory>();

  rides.forEach((ride) => {
    const categoryKey = ride.rideCategory.sv;

    // New category found
    if (!categoryMap.has(categoryKey)) {
      categoryMap.set(categoryKey, {
        category: ride.rideCategory,
        rides: {
          open: [],
          temporarilyClosed: [],
          notOperational: [],
        },
      });
    }

    // Add ride to the correct category and queue state
    const category = categoryMap.get(categoryKey);
    if (category) {
      const queueState = (() => {
        switch (ride.displayState.state) {
          case "QUEUE_TIME":
            return "open";
          case "CLOSED":
            return ride.displayState.queueData.queueState;
          case "OPENS_SOON":
            return "temporarilyClosed";
          case "NOT_OPEN_TODAY":
            return "notOperational";
        }
      })();
      category.rides[queueState].push(ride);
    }
  });

  return Array.from(categoryMap.values());
}

/**
 * Sort rides alphabetically by ride title, A-Z or Z-A
 * Based on locale "sv" (Swedish) for correct sorting of special characters (Å, Ä, Ö)
 */
function sortRidesAlphabetically(rides: Array<QueueDisplayRide>, sortMode: "aToZ" | "zToA") {
  return rides.sort((a, b) => {
    return sortMode === "aToZ"
      ? a.rideTitle.localeCompare(b.rideTitle, "sv", { sensitivity: "base" })
      : b.rideTitle.localeCompare(a.rideTitle, "sv", { sensitivity: "base" });
  });
}

/**
 * Sort rides with queue time, shortest or longest (only use for open rides)
 * Rides with the same queue time will be sorted alphabetically based on rideTitle
 */
function sortRidesByQueueTime(rides: Array<QueueDisplayRide>, sortMode: "shortest" | "longest") {
  return orderBy(
    rides,
    [
      // put open rides first, as long as it's not missing a queue time
      (ride) => ride.displayState.state === "QUEUE_TIME" && ride.displayState.queueData.queueTime !== "-",

      // sort by queuetime numerically using parseInt
      (ride) => "queueData" in ride.displayState && parseInt(ride.displayState.queueData.queueTime),

      // lastly, sort alphabetically
      "rideTitle",
    ],
    [
      "desc",
      // sortMode only applies to queuetime sort
      sortMode === "shortest" ? "asc" : "desc",
      "asc",
    ],
  );
}

/**
 * Sort rides within each category and queue state
 * Open rides are sorted by shortest queue time, then alphabetically by ride title
 * All other rides are sorted alphabetically by ride title
 */
function getSortedRides(groupedRides: Array<QueueDisplayDataCategory>): Array<QueueDisplayDataCategory> {
  return groupedRides.map((category) => ({
    ...category,
    rides: {
      open: sortRidesByQueueTime(category.rides.open, "shortest"),
      temporarilyClosed: sortRidesAlphabetically(category.rides.temporarilyClosed, "aToZ"),
      notOperational: sortRidesAlphabetically(category.rides.notOperational, "aToZ"),
    },
  }));
}

/**
 * Custom hook to fetch ride queue data and return grouped and sorted
 * @param rideBlocks
 * @param openingHours
 * @returns
 * - Undefined if openingHours are not passed or if queue times are not available from backend
 * - Rides sorted by category and queue state, with rides sorted by queue time or alphabetically by ride title
 */
export function useGroupedAndSortedRides(
  rideBlocks: Array<QueueDisplayRideBlock>,
  openingHours: OpeningHoursItem | undefined,
) {
  const { data: allQueueTimes } = useFetchAllQueueTimes({
    updateInterval: 60_000,
    includeEvents: true,
    includeHideForWeb: true,
  });

  // Return `undefined` as long as no queue times are available, to avoid displaying wrong data
  if (!allQueueTimes || !openingHours) {
    return undefined;
  }

  const rides = rideBlocks.map((ride) => {
    const rideQueueTimeObject = allQueueTimes.find((queueTime) => queueTime.attractionId === ride.rideId);
    const displayState = displayStateAndQueueData(rideQueueTimeObject, openingHours, TodayHelper.getNow());
    return {
      rideId: ride.rideId,
      rideTitle: ride.title,
      rideCategory: ride.categoryTitle,
      displayState,
    } satisfies QueueDisplayRide;
  });

  const groupedRides = getGroupedRides(rides);
  return getSortedRides(groupedRides);
}
