/** Absolute times (they carry the offset), so the stories render the same in any time zone. */
const MOCKED_NOW = new Date("2024-11-03T11:00:00+01:00");

const createEvent = ({
  id,
  title,
  start,
  end,
  cancelledText,
}: {
  id: string;
  title: string;
  start: string;
  end?: string;
  cancelledText?: string;
}): ContentfulEvent => ({
  id,
  title,
  startDateAndTime: start,
  endDateAndTime: end,
  startDateAndTimeWithTimeZone: start,
  endDateAndTimeWithTimeZone: end ?? start,
  description: "",
  externalEntry: { externalEntryId: `external-${id}` },
  cancelled: !!cancelledText,
  cancelledText: cancelledText ?? "",
});

const createOperatingTime = (opensOn: string, closesOn: string): OperatingTime => ({
  opensOn,
  closesOn,
  isOpenToPublic: true,
  operatingTimeType: OperatingTimeType.ORDINARY,
  operatingPeriodType: OperatingPeriodType.ORDINARY,
});

