// Docgen lists every Contentful block field; only these are useful as controls, the states are covered by the showcases.
const documentedProps = ["title", "mockedDate"];

const meta = {
  title: "Primitives/Daily Schedule/Schedule Row",
  component: ScheduleRow,
  decorators: [withMockedDate, withBlockWrapper],
  parameters: {
    controls: { include: documentedProps },
    docs: {
      controls: { include: documentedProps },
      description: {
        component:
          "One row in the daily schedule: image, title and today's times for a restaurant or a ride, " +
          "linking to its page when it has one. The time text depends on the mocked clock: upcoming rows " +
          'show the opening hours, open rows show "Öppen" and the closing time, rows that have closed show ' +
          '"Stängd idag" and cancelled events show "Inställd" or their own text. Rides fed from the ' +
          'attraction schedule (`contentSource: "schedule"`) also show the live stoppage state when the ' +
          "queue is not open.",
      },
    },
  },
  argTypes: {
    ...argTypesMockDate,
    queueState: { control: "select", options: queueDisplayQueueStates },
    stoppage: { control: "select", options: Object.values(PlcQueueStoppageFlag) },
  },
  args: {
    mockedDate: MOCKED_NOW,
    ...restaurant,
  },
} satisfies Meta<WithMockedDate<typeof ScheduleRow>>;

export default meta;

// Typed on the component rather than on meta: the props are a union (restaurant | ride), and with
