export const TestOpenNow: Story = {
  args: {
    event: createEvent({
      id: "open",
      title: "Snackbaren",
      start: "2024-11-03T09:00:00+01:00",
      end: "2024-11-03T18:30:00+01:00",
    }),
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    // The closing time is formatted in the browser's time zone, so only the "open" prefix is fixed.
    await expect(canvas.getByText(/^Öppen - \d{2}:\d{2}$/)).toBeVisible();
    // The link's accessible name is its whole content (image alt, heading and time), so match it loosely.
    await expect(canvas.getByRole("link", { name: /Snackbaren/ })).toHaveAttribute("href", "restauranger/snackbaren");
  },
};
