export type IPlaceholderImages = {
  eventRow: string;
  restaurantImage: string;
  rideImage: string;
  rideQueueDisplay: string;
  cartItem: string;
  sendGift: string;
  myParksGiftProduct: string;
  myParksGiftWrapper: string;
};

class PlaceholderImageHelper {
  placeholderImage: IPlaceholderImages;

  constructor() {
    this.placeholderImage = {
      eventRow: "",
      restaurantImage: "",
      rideImage: "",
      rideQueueDisplay: "",
      cartItem: "",
      sendGift: "",
      myParksGiftProduct: "",
      myParksGiftWrapper: "",
    };
  }

  setPlaceholderImages(placeholderImage: IPlaceholderImages) {
    this.placeholderImage = placeholderImage;
  }

  getPlaceholderImages() {
    return this.placeholderImage;
  }

  getPlaceholderImage(key: keyof IPlaceholderImages) {
    return this.placeholderImage[key];
  }
}

const helper = new PlaceholderImageHelper();
export default helper;
